-- DEN-2843: secret-free Shared Auth runtime identity marker.
create schema if not exists "declarative_migrations_shared_auth"; revoke all on schema "declarative_migrations_shared_auth" from public;
create table if not exists "declarative_migrations_shared_auth".runtime_identity(singleton boolean primary key default true check(singleton),github_org text not null check(github_org='declarative-migrations'),provider text not null check(provider='neon'),realm text not null check(realm='admin-auth'),database_url_env text not null check(database_url_env='NEON_ADMIN_DATABASE_URL'),contract_version smallint not null default 2 check(contract_version=2),installed_at timestamptz not null default now());
alter table "declarative_migrations_shared_auth".runtime_identity enable row level security; revoke all on table "declarative_migrations_shared_auth".runtime_identity from public;
insert into "declarative_migrations_shared_auth".runtime_identity(singleton,github_org,provider,realm,database_url_env,contract_version) values(true,'declarative-migrations','neon','admin-auth','NEON_ADMIN_DATABASE_URL',2) on conflict (singleton) do update set github_org=excluded.github_org,provider=excluded.provider,realm=excluded.realm,database_url_env=excluded.database_url_env,contract_version=excluded.contract_version;
